DROP TABLE IF EXISTS `Grid_Node`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Grid_Node` (
  `node_id` int unsigned NOT NULL AUTO_INCREMENT,
  `node_name` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `node_type` enum('SUBSTATION','TRANSFORMER','DISTRIBUTION') COLLATE utf8mb4_unicode_ci DEFAULT 'SUBSTATION',
  `location` point NOT NULL /*!80003 SRID 4326 */,
  `service_radius_km` decimal(8,3) DEFAULT '5.000',
  `max_load_mw` decimal(10,3) NOT NULL,
  `current_load_mw` decimal(10,3) DEFAULT '0.000',
  `node_status` enum('NORMAL','STRESSED','BLACKOUT','MAINTENANCE') COLLATE utf8mb4_unicode_ci DEFAULT 'NORMAL',
  `load_utilisation_pct` decimal(5,2) GENERATED ALWAYS AS (round(((`current_load_mw` / `max_load_mw`) * 100),2)) VIRTUAL COMMENT 'KPI: Real-time load utilisation percentage',
  `is_overloaded` tinyint(1) GENERATED ALWAYS AS (((`current_load_mw` / `max_load_mw`) >= 0.85)) VIRTUAL COMMENT 'KPI: 1 if node load >= 85% of max capacity',
  `parent_node_id` int unsigned DEFAULT NULL COMMENT 'Parent node in hierarchy; NULL = root substation',
  PRIMARY KEY (`node_id`),
  SPATIAL KEY `idx_node_location` (`location`),
  KEY `fk_node_parent` (`parent_node_id`),
  CONSTRAINT `fk_node_parent` FOREIGN KEY (`parent_node_id`) REFERENCES `Grid_Node` (`node_id`),
  CONSTRAINT `chk_current_load` CHECK ((`current_load_mw` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
