CREATE TABLE `P2P_Trade_Ledger` (
  `block_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `prev_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SHA-256 hash of the previous block',
  `seller_id` int unsigned NOT NULL COMMENT 'Prosumer selling energy',
  `buyer_id` int unsigned NOT NULL COMMENT 'Prosumer buying energy',
  `asset_id` int unsigned NOT NULL COMMENT 'Asset generating the energy sold',
  `energy_kwh` decimal(10,4) NOT NULL,
  `agreed_price` decimal(8,6) NOT NULL COMMENT 'Peer-negotiated price per kWh',
  `trade_amount` decimal(12,4) GENERATED ALWAYS AS (round((`energy_kwh` * `agreed_price`),4)) STORED,
  `trade_ts` timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `trade_status` enum('PENDING','CONFIRMED','DISPUTED','CANCELLED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `block_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SHA2-256 hash of this block',
  `nonce` int unsigned NOT NULL DEFAULT '0',
  `is_valid` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Set to 0 by verify procedure if tampered',
  PRIMARY KEY (`block_id`),
  KEY `fk_p2p_asset` (`asset_id`),
  KEY `idx_p2p_seller` (`seller_id`,`trade_ts`),
  KEY `idx_p2p_buyer` (`buyer_id`,`trade_ts`),
  KEY `idx_p2p_ts` (`trade_ts`),
  CONSTRAINT `fk_p2p_asset` FOREIGN KEY (`asset_id`) REFERENCES `Energy_Asset` (`asset_id`),
  CONSTRAINT `fk_p2p_buyer` FOREIGN KEY (`buyer_id`) REFERENCES `Prosumer_Account` (`prosumer_id`),
  CONSTRAINT `fk_p2p_seller` FOREIGN KEY (`seller_id`) REFERENCES `Prosumer_Account` (`prosumer_id`),
  CONSTRAINT `chk_p2p_diff_prosumers` CHECK ((`seller_id` <> `buyer_id`)),
  CONSTRAINT `chk_p2p_energy` CHECK ((`energy_kwh` > 0)),
  CONSTRAINT `chk_p2p_price` CHECK ((`agreed_price` > 0))
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Blockchain-inspired tamper-evident P2P energy trade ledger';
