/*!50106 CREATE*/ /*!50117 DEFINER=`root`@`localhost`*/ /*!50106 EVENT `grid_health_monitor` ON SCHEDULE EVERY 1 MINUTE STARTS '2026-04-05 15:16:45' ON COMPLETION NOT PRESERVE ENABLE DO BEGIN
    -- Flag overloaded nodes (avoid duplicate spam)
    INSERT INTO Grid_Event (
        event_type, node_id, severity, description, triggered_by
    )
    SELECT 
        'OVERLOAD',
        node_id,
        CASE 
            WHEN (current_load_mw / max_load_mw) >= 0.95 THEN 'CRITICAL'
            WHEN (current_load_mw / max_load_mw) >= 0.85 THEN 'WARNING'
        END,
        CONCAT(
            'Node load at ',
            ROUND((current_load_mw / max_load_mw) * 100, 1),
            '%. Load=', current_load_mw, 'MW / Max=', max_load_mw, 'MW'
        ),
        'EVENT_SCHEDULER'
    FROM Grid_Node gn
    WHERE current_load_mw / max_load_mw >= 0.85
      AND node_status != 'BLACKOUT'
      AND NOT EXISTS (
          SELECT 1 FROM Grid_Event ge
          WHERE ge.node_id = gn.node_id
            AND ge.event_type = 'OVERLOAD'
            AND ge.resolved_ts IS NULL
      );

    -- Update node status
    UPDATE Grid_Node
    SET node_status = CASE
        WHEN current_load_mw / max_load_mw >= 0.85 THEN 'STRESSED'
        ELSE 'NORMAL'
    END
    WHERE node_status NOT IN ('BLACKOUT','MAINTENANCE');

    -- Auto-resolve old events (>1 hour)
    UPDATE Grid_Event
    SET resolved_ts = NOW()
    WHERE resolved_ts IS NULL
      AND event_ts < DATE_SUB(NOW(), INTERVAL 1 HOUR)
