CREATE DEFINER=`root`@`localhost` FUNCTION `fn_battery_health_score`(p_asset_id INT) RETURNS decimal(5,2)
    READS SQL DATA
    DETERMINISTIC
BEGIN
    DECLARE v_soc DECIMAL(5,2);
    DECLARE v_cycles INT;
    DECLARE v_status VARCHAR(20);
    DECLARE v_score DECIMAL(5,2);

    -- Fetch battery details
    SELECT 
        sa.current_soc,
        sa.cycle_count,
        ea.asset_status
    INTO 
        v_soc,
        v_cycles,
        v_status
    FROM Energy_Asset ea
    JOIN Storage_Asset sa 
        ON sa.asset_id = ea.asset_id
    WHERE ea.asset_id = p_asset_id;

    -- Base score = SOC
    SET v_score = v_soc;

    -- Cycle degradation penalty
    IF v_cycles > 400 THEN
        SET v_score = v_score - 10;
    ELSEIF v_cycles > 300 THEN
        SET v_score = v_score - 5;
    END IF;

    -- Status penalty
    IF v_status <> 'ACTIVE' THEN
        SET v_score = v_score - 10;
    END IF;

    RETURN ROUND(v_score, 2);
END ;;
DELIMITER ;
