DELIMITER ;;
CREATE DEFINER=`root`@`localhost` FUNCTION `fn_dynamic_tou_price`(
    p_ts            TIMESTAMP,
    p_tariff_class  ENUM('RESIDENTIAL','COMMERCIAL','INDUSTRIAL'),
    p_demand_resp   BOOLEAN        -- TRUE = grid emergency, surge pricing active
) RETURNS decimal(8,6)
    READS SQL DATA
    DETERMINISTIC
BEGIN
    DECLARE v_hour    INT;
    DECLARE v_dow     INT;     -- 1=Sunday, 2=Monday ... 7=Saturday
    DECLARE v_month   INT;
    DECLARE v_base    DECIMAL(8,6);
    DECLARE v_season  DECIMAL(4,2);
    DECLARE v_weekend DECIMAL(4,2);
    DECLARE v_class   DECIMAL(4,2);
    DECLARE v_dr      DECIMAL(4,2);

    SET v_hour  = HOUR(p_ts);
    SET v_dow   = DAYOFWEEK(p_ts);
    SET v_month = MONTH(p_ts);

    -- ── Base rate by time-of-use band ─────────────────────────
    SET v_base = CASE
        WHEN v_hour BETWEEN 17 AND 21 THEN 0.250000   -- PEAK
        WHEN v_hour BETWEEN  7 AND 16 THEN 0.150000   -- SHOULDER
        ELSE                               0.080000   -- OFF_PEAK
    END;

    -- ── Seasonal multiplier ───────────────────────────────────
    -- Summer (Jun–Sep) and Winter (Dec–Feb) cost more due to A/C & heating
    SET v_season = CASE
        WHEN v_month IN (6,7,8,9)    THEN 1.25   -- summer surcharge
        WHEN v_month IN (12,1,2)     THEN 1.15   -- winter surcharge
        ELSE                              1.00   -- spring / autumn
    END;

    -- ── Weekend adjustment ────────────────────────────────────
    -- Lower demand on weekends → cheaper rate
    SET v_weekend = CASE
        WHEN v_dow IN (1,7) THEN 0.85   -- Saturday / Sunday discount
        ELSE                     1.00
    END;

    -- ── Tariff class volume discount ──────────────────────────
    SET v_class = CASE p_tariff_class
        WHEN 'COMMERCIAL'  THEN 0.90   -- 10% volume discount
        WHEN 'INDUSTRIAL'  THEN 0.80   -- 20% volume discount
        ELSE                    1.00
    END;

    -- ── Demand-response emergency surcharge ───────────────────
    -- Grid operator triggers DR mode; peak prices spike 50%
    SET v_dr = IF(p_demand_resp AND v_hour BETWEEN 17 AND 21, 1.50, 1.00);

    RETURN ROUND(v_base * v_season * v_weekend * v_class * v_dr, 6);
END ;;
DELIMITER ;
