CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_broadcast_fault_warnings`(IN p_faulted_node_id INT)
BEGIN
    DECLARE done INT DEFAULT FALSE;
    DECLARE cur_asset_id INT;
    DECLARE cur_asset_type VARCHAR(50);
    
    -- Using a cursor to find assets on the failing node that are NOT currently IDLE
    DECLARE asset_cursor CURSOR FOR 
        SELECT asset_id, asset_type 
        FROM Energy_Asset 
        WHERE grid_node_id = p_faulted_node_id AND asset_status != 'IDLE';
        
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

    OPEN asset_cursor;

    read_loop: LOOP
        FETCH asset_cursor INTO cur_asset_id, cur_asset_type;
        
        IF done THEN
            LEAVE read_loop;
        END IF;

        -- 1. Update status to 'IDLE' (Valid ENUM from your previous test)
        UPDATE Energy_Asset 
        SET asset_status = 'IDLE' 
        WHERE asset_id = cur_asset_id;

        -- 2. Log event using 'MAINTENANCE' (Commonly used ENUM)
        -- If 'MAINTENANCE' fails, replace it with 'OVERLOAD' which we saw in your log
        INSERT INTO Grid_Event (event_type, severity, description)
        VALUES ('MAINTENANCE', 'CRITICAL', CONCAT('Emergency shutdown triggered for ', cur_asset_type, ' ID: ', cur_asset_id));
        
    END LOOP;

    CLOSE asset_cursor;
END ;;
DELIMITER ;
