CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_calculate_grid_health`(
    OUT p_critical_count INT
)
BEGIN
    -- This scans the Grid_Node table for any substation or transformer 
    -- currently marked as STRESSED or CRITICAL.
    SELECT COUNT(*) 
    INTO p_critical_count 
    FROM Grid_Node 
    WHERE node_status IN ('STRESSED', 'CRITICAL');
END ;;
