/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_execute_secure_trade`(
    IN p_buyer_id INT, 
    IN p_seller_id INT, 
    IN p_asset_id INT,
    IN p_trade_amount DECIMAL(12,4), 
    IN p_energy_kwh DECIMAL(10,3)
)
BEGIN
    -- Variables for our blockchain ledger
    DECLARE v_prev_hash CHAR(64);
    DECLARE v_new_hash CHAR(64);

    -- Declare an exit handler for any SQL errors
    DECLARE EXIT HANDLER FOR SQLEXCEPTION 
    BEGIN
        ROLLBACK;
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Trade failed: Transaction Rolled Back';
    END;

    START TRANSACTION;

    -- 1. Deduct funds from the buyer
    UPDATE Prosumer_Account 
    SET wallet_balance = wallet_balance - p_trade_amount 
    WHERE prosumer_id = p_buyer_id;

    -- 2. Credit funds to the seller
    UPDATE Prosumer_Account 
    SET wallet_balance = wallet_balance + p_trade_amount 
    WHERE prosumer_id = p_seller_id;

    -- 3. Get the most recent hash from the ledger (or a default if it's empty)
    SELECT COALESCE(MAX(block_hash), SHA2('genesis_block', 256)) INTO v_prev_hash FROM P2P_Trade_Ledger;

    -- 4. Calculate a secure hash for the new block
    SET v_new_hash = SHA2(CONCAT(v_prev_hash, p_seller_id, p_buyer_id, CURRENT_TIMESTAMP), 256);

    -- 5. Log the transaction (now including ALL required fields)
    INSERT INTO P2P_Trade_Ledger (prev_hash, seller_id, buyer_id, asset_id, energy_kwh, agreed_price, block_hash) 
    VALUES (v_prev_hash, p_seller_id, p_buyer_id, p_asset_id, p_energy_kwh, (p_trade_amount / p_energy_kwh), v_new_hash);

    COMMIT;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
