DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_fault_propagation`(
    IN  p_fault_node_id  INT UNSIGNED
)
BEGIN
    WITH RECURSIVE fault_tree AS (
        -- Anchor: the faulted node itself (depth 0)
        SELECT  node_id,
                node_name,
                node_status,
                parent_node_id,
                0           AS depth,
                CAST(node_name AS CHAR(500)) AS path
        FROM    Grid_Node
        WHERE   node_id = p_fault_node_id

        UNION ALL

        -- Recursive: find all children of nodes already in the tree
        SELECT  gn.node_id,
                gn.node_name,
                gn.node_status,
                gn.parent_node_id,
                ft.depth + 1,
                CONCAT(ft.path, ' → ', gn.node_name)
        FROM    Grid_Node   gn
        JOIN    fault_tree  ft ON ft.node_id = gn.parent_node_id
    )
    SELECT  ft.depth,
            ft.path                             AS propagation_path,
            ft.node_id,
            ft.node_name,
            ft.node_status,
            COUNT(ea.asset_id)                  AS assets_at_risk,
            SUM(CASE WHEN ea.asset_type = 'BATTERY' THEN 1 ELSE 0 END)
                                                AS batteries_at_risk,
            ROUND(SUM(sa.dispatchable_kwh), 2)  AS dispatchable_kwh_lost
    FROM    fault_tree ft
    LEFT JOIN Energy_Asset  ea ON ea.grid_node_id = ft.node_id
    LEFT JOIN Storage_Asset sa ON sa.asset_id     = ea.asset_id
    GROUP BY ft.depth, ft.path, ft.node_id, ft.node_name, ft.node_status
    ORDER BY ft.depth, ft.node_id;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_find_nearest_batteries` */;
