/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_record_p2p_trade`(
    IN  p_seller_id    INT UNSIGNED,
    IN  p_buyer_id     INT UNSIGNED,
    IN  p_asset_id     INT UNSIGNED,
    IN  p_energy_kwh   DECIMAL(10,4),
    IN  p_price        DECIMAL(8,6),
    OUT p_block_id     BIGINT UNSIGNED,
    OUT p_block_hash   CHAR(64)
)
BEGIN
    DECLARE v_prev_hash  CHAR(64);
    DECLARE v_trade_ts   TIMESTAMP(3);
    DECLARE v_nonce      INT UNSIGNED;
    DECLARE v_hash_input TEXT;

    -- Validate seller owns the asset
    IF NOT EXISTS (
        SELECT 1 FROM Prosumer_Asset
        WHERE prosumer_id = p_seller_id AND asset_id = p_asset_id
    ) THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Seller does not own this asset — trade rejected';
    END IF;

    -- Validate buyer has sufficient wallet balance
    IF (SELECT wallet_balance FROM Prosumer_Account WHERE prosumer_id = p_buyer_id)
        < (p_energy_kwh * p_price) THEN
        SIGNAL SQLSTATE '45001'
            SET MESSAGE_TEXT = 'Buyer has insufficient wallet balance for this trade';
    END IF;

    START TRANSACTION;

    -- Get previous block hash (genesis = 64 zeros if chain is empty)
    SELECT IFNULL(block_hash, REPEAT('0', 64))
    INTO   v_prev_hash
    FROM   P2P_Trade_Ledger
    ORDER  BY block_id DESC
    LIMIT  1;

    IF v_prev_hash IS NULL THEN
        SET v_prev_hash = REPEAT('0', 64);
    END IF;

    SET v_trade_ts = NOW(3);
    SET v_nonce    = FLOOR(RAND() * 999999);

    -- Build the hash input string (mirrors blockchain block header)
    SET v_hash_input = CONCAT(
        v_prev_hash,        '|',
        p_seller_id,        '|',
        p_buyer_id,         '|',
        p_asset_id,         '|',
        p_energy_kwh,       '|',
        p_price,            '|',
        v_trade_ts,         '|',
        v_nonce
    );

    -- Compute SHA2-256 hash
    SET p_block_hash = SHA2(v_hash_input, 256);

    -- Insert the new block
    INSERT INTO P2P_Trade_Ledger
        (prev_hash, seller_id, buyer_id, asset_id,
         energy_kwh, agreed_price, trade_ts, block_hash, nonce, trade_status)
    VALUES
        (v_prev_hash, p_seller_id, p_buyer_id, p_asset_id,
         p_energy_kwh, p_price, v_trade_ts, p_block_hash, v_nonce, 'CONFIRMED');

    SET p_block_id = LAST_INSERT_ID();

    -- Transfer funds: debit buyer, credit seller
    UPDATE Prosumer_Account
    SET    wallet_balance = wallet_balance - (p_energy_kwh * p_price)
    WHERE  prosumer_id = p_buyer_id;

    UPDATE Prosumer_Account
    SET    wallet_balance = wallet_balance + (p_energy_kwh * p_price)
    WHERE  prosumer_id = p_seller_id;

    COMMIT;
END ;;
DELIMITER ;
