CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_verify_p2p_chain`()
BEGIN
    DECLARE done         INT DEFAULT 0;
    DECLARE v_id         BIGINT UNSIGNED;
    DECLARE v_prev       CHAR(64);
    DECLARE v_seller     INT UNSIGNED;
    DECLARE v_buyer      INT UNSIGNED;
    DECLARE v_asset      INT UNSIGNED;
    DECLARE v_kwh        DECIMAL(10,4);
    DECLARE v_price      DECIMAL(8,6);
    DECLARE v_ts         TIMESTAMP(3);
    DECLARE v_nonce      INT UNSIGNED;
    DECLARE v_stored     CHAR(64);
    DECLARE v_computed   CHAR(64);
    DECLARE v_input      TEXT;

    DECLARE chain_cur CURSOR FOR
        SELECT block_id, prev_hash, seller_id, buyer_id, asset_id,
               energy_kwh, agreed_price, trade_ts, nonce, block_hash
        FROM   P2P_Trade_Ledger
        ORDER  BY block_id ASC;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

    -- Temp results table
    DROP TEMPORARY TABLE IF EXISTS chain_report;
    CREATE TEMPORARY TABLE chain_report (
        block_id        BIGINT UNSIGNED,
        trade_ts        TIMESTAMP(3),
        seller_id       INT UNSIGNED,
        buyer_id        INT UNSIGNED,
        energy_kwh      DECIMAL(10,4),
        trade_amount    DECIMAL(12,4),
        stored_hash     CHAR(64),
        computed_hash   CHAR(64),
        chain_status    VARCHAR(10)
    );

    OPEN chain_cur;
    read_loop: LOOP
        FETCH chain_cur INTO v_id, v_prev, v_seller, v_buyer, v_asset,
                             v_kwh, v_price, v_ts, v_nonce, v_stored;
        IF done THEN LEAVE read_loop; END IF;

        -- Recompute hash using same formula as sp_record_p2p_trade
        SET v_input = CONCAT(
            v_prev,    '|', v_seller, '|', v_buyer,  '|',
            v_asset,   '|', v_kwh,    '|', v_price,  '|',
            v_ts,      '|', v_nonce
        );
        SET v_computed = SHA2(v_input, 256);

        INSERT INTO chain_report VALUES (
            v_id, v_ts, v_seller, v_buyer, v_kwh,
            ROUND(v_kwh * v_price, 4),
            v_stored, v_computed,
            IF(v_stored = v_computed, 'VALID', 'TAMPERED')
        );

        -- Flag tampered blocks in the live table
        IF v_stored != v_computed THEN
            UPDATE P2P_Trade_Ledger SET is_valid = 0 WHERE block_id = v_id;
        END IF;
    END LOOP;
    CLOSE chain_cur;

    -- Return the full chain integrity report
    SELECT  cr.block_id,
            cr.trade_ts,
            s.full_name    AS seller,
            b.full_name    AS buyer,
            cr.energy_kwh,
            cr.trade_amount,
            cr.chain_status,
            LEFT(cr.stored_hash,   16) AS stored_hash_preview,
            LEFT(cr.computed_hash, 16) AS computed_hash_preview
    FROM    chain_report         cr
    JOIN    Prosumer_Account      s  ON s.prosumer_id = cr.seller_id
    JOIN    Prosumer_Account      b  ON b.prosumer_id = cr.buyer_id
    ORDER   BY cr.block_id;

    -- Summary line
    SELECT  COUNT(*)                                       AS total_blocks,
            SUM(chain_status = 'VALID')                    AS valid_blocks,
            SUM(chain_status = 'TAMPERED')                 AS tampered_blocks,
            IF(SUM(chain_status = 'TAMPERED') = 0,
               'CHAIN INTEGRITY: OK', 'CHAIN INTEGRITY: COMPROMISED')
                                                           AS verdict
    FROM    chain_report;

    DROP TEMPORARY TABLE chain_report;
END ;;
DELIMITER ;
