/*!50001 VIEW `vw_tou_billing` AS select `et`.`txn_id` AS `txn_id`,`et`.`prosumer_id` AS `prosumer_id`,`pa`.`full_name` AS `full_name`,`et`.`asset_id` AS `asset_id`,`et`.`txn_type` AS `txn_type`,`et`.`energy_kwh` AS `energy_kwh`,hour(`et`.`txn_ts`) AS `txn_hour`,(case when (hour(`et`.`txn_ts`) between 17 and 21) then 'PEAK' when (hour(`et`.`txn_ts`) between 7 and 16) then 'SHOULDER' else 'OFF_PEAK' end) AS `tou_period`,(case when (hour(`et`.`txn_ts`) between 17 and 21) then 0.250000 when (hour(`et`.`txn_ts`) between 7 and 16) then 0.150000 else 0.080000 end) AS `tou_price`,round((`et`.`energy_kwh` * (case when (hour(`et`.`txn_ts`) between 17 and 21) then 0.25 when (hour(`et`.`txn_ts`) between 7 and 16) then 0.15 else 0.08 end)),4) AS `tou_cost`,round(sum((`et`.`energy_kwh` * (case when (hour(`et`.`txn_ts`) between 17 and 21) then 0.25 when (hour(`et`.`txn_ts`) between 7 and 16) then 0.15 else 0.08 end))) OVER (PARTITION BY `et`.`prosumer_id`,cast(`et`.`txn_ts` as date) ORDER BY `et`.`txn_ts` ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) ,4) AS `running_daily_total`,`et`.`txn_ts` AS `txn_ts`,`et`.`txn_status` AS `txn_status` from (`energy_transaction` `et` join `prosumer_account` `pa` on((`pa`.`prosumer_id` = `et`.`prosumer_id`))) where (`et`.`txn_status` = 'COMMITTED') */;
